import { Test } from 'ts-toolbelt'
import { ChoiceColumn } from '../types/Choice'
import { type TypeOf, type } from '../Column'

const testA = ChoiceColumn({
    choices: {
        one: '1',
        two: '2',
    },
    default: 'two',
})

const testB = ChoiceColumn({ [type]: {} as string })

const testC = ChoiceColumn({})

type TestA = typeof testA
type TestB = typeof testB
type TestC = typeof testC

type IsKeyOf<K extends PropertyKey, T> = K extends keyof T ? true : false

Test.checks([
    Test.check<keyof TestA['choices'], 'one' | 'two', Test.Pass>(),
    Test.check<TypeOf<TestA>, keyof TestA['choices'], Test.Pass>(),
    Test.check<TestA['choices']['one'], '1', Test.Pass>(),
    Test.check<TestA['choices']['two'], '2', Test.Pass>(),
    Test.check<TestA['default'], 'two', Test.Pass>(),
    Test.check<IsKeyOf<'label', TestA>, false, Test.Pass>(),
    Test.check<IsKeyOf<'mandatory', TestA>, false, Test.Pass>(),
    Test.check<IsKeyOf<'readonly', TestA>, false, Test.Pass>(),
    Test.check<TypeOf<TestB>, string, Test.Pass>(),
    Test.check<IsKeyOf<'default', TestB>, false, Test.Pass>(),
    Test.check<IsKeyOf<'choices', TestB>, false, Test.Pass>(),
    Test.check<TypeOf<TestC>, string | number, Test.Pass>(),
    Test.check<IsKeyOf<'default', TestC>, false, Test.Pass>(),
    Test.check<IsKeyOf<'choices', TestC>, false, Test.Pass>(),
])

ChoiceColumn({
    choices: {
        one: {
            language: 'en',
            label: 'hello', // label is required
        },
    },
})

ChoiceColumn({
    choices: {
        // @ts-expect-error Missing required label
        one: {
            language: 'en',
        },
    },
})

ChoiceColumn({
    choices: {
        // @ts-expect-error Number is not a valid choice value
        one: 123,
    },
})

ChoiceColumn({
    default: 'hello', // any string or number
})

ChoiceColumn({
    default: 123, // any string or number
})

ChoiceColumn({
    [type]: {} as string,
    default: 'hello', // any string
})

ChoiceColumn({
    [type]: {} as string,
    // @ts-expect-error Must be a string
    default: 123,
})

ChoiceColumn({
    // @ts-expect-error Type must extend string or number
    [type]: {} as boolean, // ERROR: Doesn't extend string or number
})

ChoiceColumn({
    default: 'one', // Either 'one' or 'two'
    choices: {
        one: '1',
        two: '2',
    },
})

ChoiceColumn({
    default: 'two', // Either 'one' or 'two'
    choices: {
        one: '1',
        two: '2',
    },
})

ChoiceColumn({
    choices: { one: '1', two: '2' },
    default: 'three',
})

ChoiceColumn({
    // @ts-expect-error Type must extend choices
    [type]: {} as string,
    choices: {
        one: '1',
        two: '2',
    },
})

ChoiceColumn({
    [type]: 'one', // Type that extends choices is ok
    default: 'one', // Constrained by type, not choices
    choices: {
        one: '1',
        two: '2',
    },
})

ChoiceColumn({
    [type]: 'one',
    choices: { one: '1', two: '2' },
    default: 'two',
})

ChoiceColumn({
    // @ts-expect-error Must be of type Choice
    choices: ['one', 2],
    default: 'one',
})

ChoiceColumn({
    // @ts-expect-error Must be of type Choice
    choices: ['one', 2],
    default: 2,
})

ChoiceColumn({
    // @ts-expect-error Must be of type Choice
    choices: ['one', 2],
    default: 'two',
})

ChoiceColumn({
    // @ts-expect-error Must be of type Choice
    choices: ['one', { label: 'test' }],
    default: 'one',
})
